-- ----------------------------------------------
-- CUSTOMER_MASTER
-- ----------------------------------------------
DROP TABLE IF EXISTS customer_master;
CREATE TABLE customer_master (
    data_date DATE,
    region TEXT,
    department_id TEXT,
    branch_name TEXT,
    branch_id TEXT,
    portfolio_id TEXT,
    rm_name TEXT,
    cif TEXT,
    id_card TEXT,
    full_name TEXT,
    dob DATE,
    age BIGINT,
    phone TEXT,
    gender TEXT,
    segment TEXT,
    tier_name TEXT,
    tier_start_date DATE,
    tier_end_date DATE,
    total_assets NUMERIC(24,6),
    address TEXT
);
CREATE INDEX idx_customer_master_cif ON customer_master(cif);
COMMIT;
